    "isFree": false,
    "xpReward": 35,
    "orderIndex": 70,
    "estimatedMinutes": 18,
    "description": "crónica histórica: cultura y tradiciones.",
    "intro": "Lee para identificar el tema, las perspectivas, la evidencia y la conclusión.",
    "mission": "Describir prácticas sin generalizar",
    "grammar": "",
    "phrases": [],
